import fs from 'fs';
import path from 'path';

const transcriptPath = 'C:\\Users\\U-ser\\.gemini\\antigravity\\brain\\a812c987-f1b1-470b-8001-05e402a20838\\.system_generated\\logs\\transcript_full.jsonl';

const fileContent = fs.readFileSync(transcriptPath, 'utf8');
const lines = fileContent.split('\n');

for (let i = lines.length - 1; i >= 0; i--) {
  if (!lines[i].trim()) continue;
  try {
    const obj = JSON.parse(lines[i]);
    if (obj.type === 'USER_INPUT' || (obj.content && obj.content.includes('Elementary National Exam'))) {
      console.log(`Step ${obj.step_index}, type: ${obj.type}, length: ${obj.content?.length}`);
      // Save content to a temporary json file for processing
      if (obj.content && obj.content.includes('Elementary National Exam')) {
        fs.writeFileSync('d:\\passkru\\PassKru\\server\\raw_user_math_data.txt', obj.content, 'utf8');
        console.log("Saved raw user math data to file!");
        break;
      }
    }
  } catch (e) {
    // ignore
  }
}
